module.exports = new class CompletionFS {
    // Returns a list of file/folder names under currentFolder that match the given options.
    // currentFolder may be a partial path typed by the user (e.g. 'src/', 'lib/u').
    async readdir(currentFolder, options) {
        options = {
            files: true,
            folders: true,
            fileRegex: /.*/,
            folderRegex: /.*/,
            ...options
        }
        const fsp = require('node:fs/promises');
        const path = require('node:path');

        // Detect the path separator from the typed prefix so completions use the same style.
        // Group 1 captures '\' (Windows), group 0 captures '/' (Unix); default to '/'.
        const match = /\/|(\\)[^\s]/.exec(currentFolder);
        const separationChar = match?.[1] || match?.[0] || '/';
        let folder = currentFolder || process.cwd();

        let entries;
        try {
            entries = await fsp.readdir(folder, { withFileTypes: true });
        } catch {
            // currentFolder was a partial filename (not a directory) — list its parent instead.
            folder = path.dirname(folder);
            entries = await fsp.readdir(folder, { withFileTypes: true });
        }
        // When listing the cwd, use relative names (e.g. 'src/') rather than absolute paths.
        const isCwd = folder === '.' || folder === process.cwd();

        entries = entries
            .filter(e =>
                options.folders && e.isDirectory() && e.name.match(options.folderRegex)
                || options.files && e.isFile() && e.name.match(options.fileRegex))
            .map(e => {
                const name = isCwd
                    ? e.name
                    : (folder + separationChar + e.name).replace(/\\{2,}/g, '\\').replace(/\/{2,}/g, '/');
                return e.isDirectory() ? name + separationChar : name;
            });

        if (entries.length === 0) {
            entries.push(folder);
        }
        return entries;
    }

    // Returns the names of available project template directories (used by `cds init --add`).
    // argv: template names to exclude in addition to the built-in 'nodejs' and 'java' ones.
    async readTemplates(argv) {
        const fsp = require('node:fs/promises');
        const path = require('node:path');

        const excludes = ['nodejs', 'java', ...argv];

        return (await fsp.readdir(path.join(__dirname, '../../lib/init/template'), { withFileTypes: true }))
            .filter(e =>
                e.isDirectory()
                && !e.name.startsWith('_')
                && !excludes.includes(e.name))
            .map(e => e.name);
    }
}
